def brute(x, arr):
	res = arr[0] ^ x
	for i in range(1, len(arr)):
		res |= arr[i] ^ x
	return res

def soln(n, arr):
	maxm = max(arr)
	return (maxm, brute(maxm, arr))
for _ in range(int(input())):
	n = int(input())
	arr = list(map(int, input().split()))
	print(*soln(n, arr))
